BLOCK = 1_000_000
def refill():
    start = etcd.atomic_incr('/idgen/' + region) * BLOCK   # one RPC per million keys
    return range(start, start + BLOCK)

def next_key():
    if remaining() < 0.1 * BLOCK: refill_async()
    n = block.pop()
    p = feistel_permute(n, rounds=4, key=SECRET, domain=62**7)  # cycle-walk if out of domain
    return base62(p).rjust(7, '0')

ALPHA = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
def base62(n):
    s = ''
    while n > 0:
        n, r = divmod(n, 62)
        s = ALPHA[r] + s
    return s or '0'
